  WITH projetos_base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
          SELECT p.id AS projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             p.codigo AS projeto_codigo,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             p.nome AS projeto_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             p.status AS projeto_status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             p.valor_total AS projeto_valor_total,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             p.empresa_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             e.nome AS empresa_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             p.area_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
             a.nome AS area_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             p.cliente_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             c.razao_social AS cliente_razao_social,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             c.cnpj AS cliente_cnpj                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
            FROM projetos p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
              LEFT JOIN empresas e ON e.id = p.empresa_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
              LEFT JOIN areas a ON a.id = p.area_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
              LEFT JOIN clientes c ON c.id = p.cliente_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         ), mkp_base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
          SELECT mkp_parametros.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             COALESCE(mkp_parametros.perc_risco, 0::numeric) AS perc_risco,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             COALESCE(mkp_parametros.perc_inflacao, 0::numeric) AS perc_inflacao,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             COALESCE(mkp_parametros.perc_gerencia, 0::numeric) AS perc_gerencia,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             COALESCE(mkp_parametros.perc_mb_esperado, 0::numeric) AS perc_mb_mkp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             COALESCE(mkp_parametros.perc_treinamento, 0::numeric) AS perc_treinamento,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
             COALESCE(mkp_parametros.perc_custo_direto, 0.7) AS perc_custo_direto,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             COALESCE(mkp_parametros.bdi_venda, 1.4285) AS bdi_venda                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
            FROM mkp_parametros                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         ), producao_mes AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
          SELECT s.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             first_of_month(d_o.data) AS mes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             sum(dp.valor_total) AS poc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN lpu.bdi > 0::numeric THEN dp.valor_total / lpu.bdi                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                     WHEN mkp_1.bdi_venda > 0::numeric THEN dp.valor_total / mkp_1.bdi_venda                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                     ELSE dp.valor_total * COALESCE(mkp_1.perc_custo_direto, 0.7)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 END) AS custo_direto_orcado_producao                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
            FROM diario_producao dp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
              JOIN diarios_obra d_o ON d_o.id = dp.diario_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
              JOIN sites s ON s.id = d_o.site_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
              LEFT JOIN itens_lpu lpu ON lpu.id = dp.item_lpu_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
              LEFT JOIN mkp_base mkp_1 ON mkp_1.projeto_id = s.projeto_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           GROUP BY s.projeto_id, (first_of_month(d_o.data))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         ), custo_mes AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
          SELECT custo_real_erp.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             first_of_month(custo_real_erp.data_competencia) AS mes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Mão de Obra'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS mo_obra,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Materiais'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS materiais,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Equipamentos'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS equipamentos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Transporte'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS transporte,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Indiretos'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS indiretos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Financeiros'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS financeiros,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna = 'Gerência'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS gerencia_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna <> ALL (ARRAY['Mão de Obra'::text, 'Materiais'::text, 'Equipamentos'::text, 'Transporte'::text, 'Indiretos'::text, 'Financeiros'::text, 'Gerência'::text]) THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                              +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS outros,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna <> ALL (ARRAY['Gerência'::text, 'Financeiros'::text]) THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS custo_direto_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             sum(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                     WHEN custo_real_erp.categoria_interna <> 'Financeiros'::text THEN custo_real_erp.valor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                     ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 END) AS custo_total_real                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
            FROM custo_real_erp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           WHERE custo_real_erp.projeto_id IS NOT NULL AND custo_real_erp.data_competencia IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           GROUP BY custo_real_erp.projeto_id, (first_of_month(custo_real_erp.data_competencia))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         ), fat_mes AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
          SELECT faturamentos.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             first_of_month(faturamentos.data_emissao) AS mes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             sum(faturamentos.valor_bruto) AS faturamento_bruto,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             sum(faturamentos.valor_liquido) AS faturamento_liquido,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             count(*) AS qtd_faturas                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
            FROM faturamentos                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           GROUP BY faturamentos.projeto_id, (first_of_month(faturamentos.data_emissao))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         ), meses AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
          SELECT producao_mes.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             producao_mes.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
            FROM producao_mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         UNION                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
          SELECT custo_mes.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             custo_mes.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
            FROM custo_mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         UNION                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
          SELECT fat_mes.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             fat_mes.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
            FROM fat_mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         ), impostos_base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
          SELECT projeto_impostos.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             COALESCE(projeto_impostos.perc_total_impostos, 0::numeric) AS perc_total_impostos                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
            FROM projeto_impostos                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SELECT m.projeto_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     m.mes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     EXTRACT(year FROM m.mes)::integer AS ano,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     EXTRACT(month FROM m.mes)::integer AS mes_numero,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     to_char(m.mes::timestamp with time zone, 'YYYY-MM'::text) AS ano_mes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     to_char(m.mes::timestamp with time zone, 'MM/YYYY'::text) AS referencia,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     pb.projeto_codigo,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     pb.projeto_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     pb.projeto_status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     pb.area_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     pb.area_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     pb.cliente_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     pb.cliente_razao_social AS cliente,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     pb.cliente_cnpj,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     pb.empresa_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     pb.empresa_nome,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(pm.poc, 0::numeric) AS poc,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     COALESCE(imp.perc_total_impostos, 0::numeric) AS perc_impostos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)) AS receita_liquida,                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     COALESCE(cm.mo_obra, 0::numeric) AS mo_obra,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
     COALESCE(cm.materiais, 0::numeric) AS materiais,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(cm.transporte, 0::numeric) AS transporte,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     COALESCE(cm.equipamentos, 0::numeric) AS equipamentos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     COALESCE(cm.indiretos, 0::numeric) AS indiretos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(cm.outros, 0::numeric) AS outros,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     COALESCE(cm.custo_direto_real, 0::numeric) AS custo_direto_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) AS custo_direto_orcado,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) - COALESCE(cm.custo_direto_real, 0::numeric) AS resultado_direto,                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             WHEN COALESCE(pm.poc, 0::numeric) > 0::numeric THEN COALESCE(pm.custo_direto_orcado_producao, 0::numeric) / COALESCE(pm.poc, 0::numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             ELSE COALESCE(mkp.perc_custo_direto, 0.7)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         END AS perc_custo_direto_orcado,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             WHEN COALESCE(pm.poc, 0::numeric) > 0::numeric THEN COALESCE(cm.custo_direto_real, 0::numeric) / COALESCE(pm.poc, 0::numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         END AS perc_custo_direto_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     COALESCE(cm.gerencia_real, 0::numeric) AS gerencia_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * COALESCE(mkp.perc_gerencia, 0::numeric) AS gerencia_orcada,                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * COALESCE(mkp.perc_gerencia, 0::numeric) - COALESCE(cm.gerencia_real, 0::numeric) AS gerencia_resultado,                                                                                                                                                                                                                                                                                                                                                                                                                         +
         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             WHEN COALESCE(cm.custo_direto_real, 0::numeric) > 0::numeric THEN COALESCE(cm.gerencia_real, 0::numeric) / COALESCE(cm.custo_direto_real, 0::numeric)                                                                                                                                                                                                                                                                                                                                                                                                                           +
             ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         END AS perc_gerencia_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     COALESCE(mkp.perc_gerencia, 0::numeric) AS perc_gerencia_orcada,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(cm.custo_total_real, 0::numeric) AS custo_total_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * (1::numeric + COALESCE(mkp.perc_risco, 0::numeric) + COALESCE(mkp.perc_gerencia, 0::numeric)) * (1::numeric + COALESCE(mkp.perc_inflacao, 0::numeric) + COALESCE(mkp.perc_treinamento, 0::numeric)) AS custo_total_orcado,                                                                                                                                                                                                                                                                                                      +
     COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * (1::numeric + COALESCE(mkp.perc_risco, 0::numeric) + COALESCE(mkp.perc_gerencia, 0::numeric)) * (1::numeric + COALESCE(mkp.perc_inflacao, 0::numeric) + COALESCE(mkp.perc_treinamento, 0::numeric)) - COALESCE(cm.custo_total_real, 0::numeric) AS resultado_total,                                                                                                                                                                                                                                                             +
     COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)) - COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * (1::numeric + COALESCE(mkp.perc_risco, 0::numeric) + COALESCE(mkp.perc_gerencia, 0::numeric)) * (1::numeric + COALESCE(mkp.perc_inflacao, 0::numeric) + COALESCE(mkp.perc_treinamento, 0::numeric)) AS mb_orcada,                                                                                                                                                                                                                 +
     COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)) - COALESCE(cm.custo_total_real, 0::numeric) AS mb_real,                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             WHEN (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric))) > 0::numeric THEN (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)) - COALESCE(pm.custo_direto_orcado_producao, 0::numeric) * (1::numeric + COALESCE(mkp.perc_risco, 0::numeric) + COALESCE(mkp.perc_gerencia, 0::numeric)) * (1::numeric + COALESCE(mkp.perc_inflacao, 0::numeric) + COALESCE(mkp.perc_treinamento, 0::numeric))) / (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)))+
             ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         END AS perc_mb_orcada,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             WHEN (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric))) > 0::numeric THEN (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)) - COALESCE(cm.custo_total_real, 0::numeric)) / (COALESCE(pm.poc, 0::numeric) * (1::numeric - COALESCE(imp.perc_total_impostos, 0::numeric)))                                                                                                                                                                                                                  +
             ELSE 0::numeric                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         END AS perc_mb_real,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
     COALESCE(mkp.perc_mb_mkp, 0::numeric) AS perc_mb_mkp,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     COALESCE(fm.faturamento_bruto, 0::numeric) AS faturamento_bruto,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     COALESCE(fm.faturamento_liquido, 0::numeric) AS faturamento_liquido,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     COALESCE(fm.qtd_faturas, 0::bigint) AS qtd_faturas,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     COALESCE(cm.financeiros, 0::numeric) AS custo_financeiros                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
    FROM meses m                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
      JOIN projetos_base pb ON pb.projeto_id = m.projeto_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
      LEFT JOIN producao_mes pm ON pm.projeto_id = m.projeto_id AND pm.mes = m.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
      LEFT JOIN custo_mes cm ON cm.projeto_id = m.projeto_id AND cm.mes = m.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
      LEFT JOIN fat_mes fm ON fm.projeto_id = m.projeto_id AND fm.mes = m.mes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
      LEFT JOIN mkp_base mkp ON mkp.projeto_id = m.projeto_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
      LEFT JOIN impostos_base imp ON imp.projeto_id = m.projeto_id;

